// Mapping
function eMat(tx){
  var nm=tx.replace(/\s+/g,'').toLowerCase();
  var db=eGMDB();
  for(var i=0;i<db.length;i++){
    var mo=db[i],ps=mo.pattern||[];
    for(var j=0;j<ps.length;j++){
      var pn=ps[j].replace(/\s+/g,'').toLowerCase();
      if(nm.indexOf(pn)>=0||pn.indexOf(nm)>=0){
        var ic=eLC().some(function(c){return c.label===mo.label;});
        return{label:mo.label,codes:mo.codes,note:mo.note||null,source:ic?'custom':'mapping'};
      }
    }
  }return null;
}

// Analyze
var eRes2=[],eEI=null,ePM2='g';
async function eAnalyze(){
  var ks=Object.keys(eSel);if(!ks.length){eTst2('부위를 먼저 선택하세요');return;}
  var res=[],nai=[];
  ks.forEach(function(k){
    var line=k+' '+eSel[k],mo=eMat(line);
    if(mo)res.push({description:line,label:mo.label,codes:mo.codes,note:mo.note,source:mo.source});
    else{res.push({description:line,codes:[],source:'pending',note:null});nai.push(line);}
  });
  eRR(res);
  if(!nai.length)return;
  var k=eAK.value.trim();if(!k){eTst2('AI분석: API 키 필요');return;}
  eLdr2(true,'AI 분석 중...');document.getElementById('eAB').disabled=true;
  var ds=EDB.filter(function(r){return r.p>0;}).slice(0,500).map(function(r){return r.c+'|'+r.n+'|'+r.t+'|'+r.p;}).join('\n');
  try{
    var resp=await fetch('https://api.anthropic.com/v1/messages',{
      method:'POST',
      headers:{'Content-Type':'application/json','x-api-key':k,'anthropic-version':'2023-06-01','anthropic-dangerous-direct-browser-access':'true'},
      body:JSON.stringify({model:'claude-sonnet-4-20250514',max_tokens:2000,
        system:'KGM 견적전문가. BOLT 작업코드 매핑.\n교환도장=탈부착+오버홀+도장, 판금도장=판금+보수도장, 수리도장=오버홀+보수도장\nLH=좌,RH=우\nDB:\n'+ds+'\nJSON만: {"items":[{"description":"","codes":[{"code":"","name":"","type":""}],"note":""}]}',
        messages:[{role:'user',content:'변환:\n'+nai.join('\n')}]})
    });
    if(resp.ok){
      var d=await resp.json();
      var mo=d.content[0].text.match(/\{[\s\S]*\}/);
      if(mo){
        var ai=JSON.parse(mo[0]).items||[];var x=0;
        for(var i=0;i<res.length;i++){if(res[i].source==='pending'&&x<ai.length){res[i]=Object.assign({},ai[x],{source:'ai'});x++;}}
        eRR(res);
      }
    }
  }catch(e){eTst2('AI오류:'+e.message);}
  finally{eLdr2(false);document.getElementById('eAB').disabled=false;}
}

function eGP(c){var r=EBC[c];if(!r)return 0;return ePM2==='i'?r.pi:r.p;}
function eSetPM(m){
  ePM2=m;
  document.getElementById('eBG').className=m==='g'?'active':'';
  document.getElementById('eBI').className=m==='i'?'active':'';
  if(eRes2.length)eRR(eRes2);
}

function eRR(items){
  eRes2=items;var a=document.getElementById('eRes');
  if(!items.length){a.innerHTML='<div class="eem"><div style="font-size:30px;opacity:.3"></div></div>';document.getElementById('eSBar').style.display='none';return;}
  var tp=0,tc=0,n=0,rows='';
  items.forEach(function(item,idx){
    var codes=item.codes||[];
    var part=item.description||item.label||'';
    var lb={mapping:'매핑DB',ai:'AI',custom:'내저장',pending:'분석중'}[item.source]||'';
    codes.forEach(function(c,ci){
      var p=eGP(c.code);if(p>0)tp+=p;tc++;n++;
      var dr=EBC[c.code]||{};
      var priceStr=p>0?p.toLocaleString()+'원':'<span style="color:var(--text-dim)">-</span>';
      rows+='<tr class="etbl-row'+(ci===0?' etbl-grp-row':'')+'">'
        +'<td class="etr-n">'+n+'</td>'
        +'<td class="etr-part">'+(ci===0?part:'')+'</td>'
        +'<td class="etr-code" data-edit="code" data-idx="'+idx+'" data-ci="'+ci+'" title="클릭하여 편집">'+(c.code||'<em style="color:var(--text-dim);font-style:italic;font-size:10px">미입력</em>')+'</td>'
        +'<td class="etr-name" data-edit="name" data-idx="'+idx+'" data-ci="'+ci+'" title="클릭하여 편집">'+(c.name||dr.n||'')+'</td>'
        +'<td class="etr-type" data-edit="type" data-idx="'+idx+'" data-ci="'+ci+'" title="클릭하여 편집">'+(c.type||dr.t||'')+'</td>'
        +'<td class="etr-price'+(ePM2==='i'?' ins':'')+'">'+priceStr+'</td>'
        +'<td class="etr-act"><button class="etr-del" data-del-idx="'+idx+'" data-del-ci="'+ci+'">×</button></td>'
        +'</tr>';
    });
    rows+='<tr class="etbl-foot-row">'
      +'<td></td><td colspan="4">'
      +'<button class="etbl-add-btn" data-add-idx="'+idx+'">+ 행 추가</button>'
      +'<button class="etbl-sv-btn" data-sv-idx="'+idx+'"> 저장</button>'
      +(item.note?'<span style="margin-left:8px;font-size:10px;color:var(--text-dim)"> '+item.note+'</span>':'')
      +'</td><td></td><td></td>'
      +'</tr>';
  });
  a.innerHTML='<table class="etbl">'
    +'<colgroup><col style="width:32px"><col style="width:88px"><col style="width:112px"><col><col style="width:58px"><col style="width:92px"><col style="width:30px"></colgroup>'
    +'<thead><tr><th>#</th><th>부위</th><th>코드</th><th>작업명</th><th>분류</th><th style="text-align:right">공임</th><th></th></tr></thead>'
    +'<tbody>'+rows+'</tbody>'
    +'</table>';
  a.onclick=function(e){
    var del=e.target.closest('[data-del-idx]');
    if(del){eDelC(+del.getAttribute('data-del-idx'),+del.getAttribute('data-del-ci'));return;}
    var add=e.target.closest('[data-add-idx]');
    if(add){eAddC(+add.getAttribute('data-add-idx'));return;}
    var sv=e.target.closest('[data-sv-idx]');
    if(sv){eSvMap(+sv.getAttribute('data-sv-idx'));return;}
    var cell=e.target.closest('[data-edit]');
    if(cell&&!cell.querySelector('input'))eCellEdit(cell);
  };
  document.getElementById('eSBar').style.display='flex';
  document.getElementById('eSC').textContent=items.length;
  document.getElementById('eSCd').textContent=tc;
  document.getElementById('eST').textContent='₩'+tp.toLocaleString();
  eUpdateSum(tp);
}

function eUpdateSum(tp){
  var body=document.getElementById('eSumBody');
  var foot=document.getElementById('eSumFoot');
  if(!eRes2||!eRes2.length){body.innerHTML='<div class="esum-empty">부위 선택 → 추출 후<br>여기에 표시됩니다</div>';foot.style.display='none';return;}
  var rows='';
  eRes2.forEach(function(item){
    var part=item.description||item.label||'';
    rows+='<tr class="esum-grp"><td colspan="3">'+part+'</td></tr>';
    (item.codes||[]).forEach(function(c){
      var p=eGP(c.code);var dr=EBC[c.code]||{};
      rows+='<tr>'
        +'<td style="font-family:\'JetBrains Mono\',monospace;color:var(--blue);font-weight:600">'+(c.code||'-')+'</td>'
        +'<td style="color:var(--text)">'+(c.name||dr.n||'')+'</td>'
        +'<td style="text-align:right;font-family:\'JetBrains Mono\',monospace;color:var(--green);font-weight:700">'+(p>0?p.toLocaleString()+'':'—')+'</td>'
        +'</tr>';
    });
  });
  body.innerHTML='<table class="esum-tbl"><thead><tr><th>코드</th><th>작업명</th><th style="text-align:right">공임</th></tr></thead><tbody>'+rows+'</tbody></table>';
  foot.style.display='flex';
  document.getElementById('eSumTotal').textContent='₩'+(tp||0).toLocaleString();
}

function eCellEdit(cell){
  var field=cell.getAttribute('data-edit');
  var idx=+cell.getAttribute('data-idx');
  var ci=+cell.getAttribute('data-ci');
  var cur=(eRes2[idx]&&eRes2[idx].codes[ci])?eRes2[idx].codes[ci][field]||'':'';
  var inp=document.createElement('input');
  inp.className='etbl-inp';
  inp.value=cur;
  inp.placeholder=field==='code'?'코드':field==='name'?'작업명':'분류';
  cell.innerHTML='';cell.appendChild(inp);
  inp.focus();inp.select();
  function save(){if(eRes2[idx]&&eRes2[idx].codes[ci])eRes2[idx].codes[ci][field]=inp.value.trim();eRR(eRes2);}
  inp.onblur=save;
  inp.onkeydown=function(e){if(e.key==='Enter'){e.preventDefault();inp.blur();}if(e.key==='Escape'){eRR(eRes2);}};
}
function eCanEd(idx){eRR(eRes2);}
function eDelC(idx,ci){eRes2[idx].codes.splice(ci,1);if(!eRes2[idx].codes.length)eRes2.splice(idx,1);eRR(eRes2);}
function eAddC(idx){if(!eRes2[idx].codes)eRes2[idx].codes=[];eRes2[idx].codes.push({code:'',name:'',type:''});eRR(eRes2);}
function eSvMap(idx){
  var item=eRes2[idx];if(!item||!item.codes||!item.codes.length){eTst2('저장할 코드 없음');return;}
  var label=item.description||item.label||'';
  var custom=eLC();var ex=custom.findIndex(function(c){return c.label===label;});
  var entry={label:label,pattern:[label,label.replace(/\s+/g,'')],
    codes:item.codes.map(function(c){return{code:c.code,name:c.name,type:c.type};}),
    note:item.note||null,savedAt:new Date().toLocaleDateString('ko-KR')};
  if(ex>=0)custom[ex]=entry;else custom.unshift(entry);
  eSC2(custom);
  if(window.fsSaveMp)window.fsSaveMp(entry).then(function(ok){eTst2(ok?'저장+동기화완료!':'로컬저장완료');});
  else eTst2('저장완료!');
  eRes2[idx].source='custom';eEI=null;eRR(eRes2);
}

// Search
function eDoSearch(q){
  var res=document.getElementById('eSrchRes');
  var tf=document.getElementById('eSrchType').value;
  q=q.trim();
  if(!q){res.innerHTML='<div class="esrch-empty">검색하면 결과가 나옵니다 · DB '+EDB.length.toLocaleString()+'건</div>';return;}
  var isNum=/^[0-9A-Za-z]+$/.test(q);
  var filtered=EDB.filter(function(r){
    var mq=isNum?(r.c.indexOf(q)===0):(r.n.indexOf(q)===0||r.n.indexOf(q)>=0);
    return mq&&(!tf||r.t===tf)&&(r.p>0||r.pi>0);
  }).slice(0,50);
  if(!filtered.length){res.innerHTML='<div class="esrch-empty">"'+q+'" 검색 결과 없음</div>';return;}
  var h='<div class="esrch-cnt">'+filtered.length+'건'+(filtered.length===50?' (상위50건)':'')+'</div>';
  h+='<div class="esrch-colhdr"><span>코드</span><span>작업명</span><span>분류</span><span>공임</span><span></span></div>';
  // data 속성 사용, onclick 없음 → 이벤트 위임
  h+=filtered.map(function(r){
    var price=ePM2==='i'?r.pi:r.p;
    var safeName=r.n.replace(/"/g,'&quot;');
    return '<div class="esrch-row">'
      +'<span class="esrch-code">'+r.c+'</span>'
      +'<span class="esrch-name">'+r.n+'</span>'
      +'<span class="esrch-type">'+(r.t||'')+'</span>'
      +'<span class="esrch-price">'+(price>0?price.toLocaleString()+'원':'-')+'</span>'
      +'<button class="esrch-add" data-c="'+r.c+'" data-n="'+safeName+'" data-t="'+(r.t||'')+'">+추가</button>'
      +'</div>';
  }).join('');
  res.innerHTML=h;
}
function eAddFromSearch(code,name,type){
  var direct=eRes2.findIndex(function(r){return r.label==='직접 추가';});
  if(direct>=0)eRes2[direct].codes.push({code:code,name:name,type:type});
  else eRes2.push({description:'직접 추가',label:'직접 추가',codes:[{code:code,name:name,type:type}],note:null,source:'mapping'});
  eRR(eRes2);eTst2(name+' 추가됨');
}

// Cloud
async function eCSave(){
  if(!eRes2.length){eTst2('저장할 견적 없음');return;}
  var tp=0;eRes2.forEach(function(r){(r.codes||[]).forEach(function(c){tp+=eGP(c.code);});});
  var est={
    vehicle:{model:document.getElementById('eMd').textContent,vin:document.getElementById('eVn').textContent,
      plate:document.getElementById('ePl').textContent,year:document.getElementById('eYr').textContent},
    items:eRes2,totalPrice:tp,priceMode:ePM2,date:new Date().toLocaleDateString('ko-KR')
  };
  // 연동된 차량 레코드 ID가 있으면 견적에 포함
  if(window._estimateLinkedRecordId){
    est.recordId=window._estimateLinkedRecordId;
    est.carNum=window._estimateLinkedCarNum||'';
  }
  if(window.fsSaveEst){
    var id=await window.fsSaveEst(est);
    if(id){
      eTst2('견적저장완료!');
      // 연동된 차량이 있으면 수리비용(cost)과 estimateId 자동 반영
      if(window._estimateLinkedRecordId && window._fbUpdate && window._fbRef && window._fbDb){
        try{
          var recRef=window._fbRef(window._fbDb,'records/'+window._estimateLinkedRecordId);
          await window._fbUpdate(recRef,{cost:tp,estimateId:id,updatedAt:new Date().toISOString()});
          eTst2('견적저장+수리비용 '+tp.toLocaleString()+'원 자동반영!');
        }catch(e){
          console.error('수리비용 자동반영 실패:',e);
          eTst2('견적저장완료 (수리비용 반영 실패)');
        }
      }
    }else{eTst2('저장실패');}
  }
  else eTst2('Firestore 연결 대기');
}
async function eHist(){
  if(!window.fsLoadEst){eTst2('Firestore 연결 대기');return;}
  var es=await window.fsLoadEst();
  var msg=es.length?es.map(function(e){var v=e.vehicle||{};return(v.plate||v.model||'차량')+' ('+e.date+') ₩'+(e.totalPrice||0).toLocaleString();}).join('\n'):'저장된 견적 없음';
  alert(' 견적내역\n\n'+msg);
}
function eCopyAll(){
  var cs=[];eRes2.forEach(function(r){(r.codes||[]).forEach(function(c){if(c.code)cs.push(c.code);});});
  navigator.clipboard.writeText(cs.join('\n')).then(function(){eTst2(cs.length+'개 복사');});
}
function eExpCSV(){
  if(!eRes2.length){eTst2('결과 없음');return;}
  var m=document.getElementById('eMd').textContent,v=document.getElementById('eVn').textContent;
  var rows=['KGM 견적서','차종:'+m+'/차대:'+v,'','번호,항목,코드,작업명,분류,공임'];
  var t=0;
  eRes2.forEach(function(r,i){
    (r.codes||[]).forEach(function(c){
      var p=eGP(c.code);t+=p;
      var desc=r.description||'';var nm=c.name||'';var tp2=c.type||'';
      rows.push((i+1)+','+JSON.stringify(desc)+','+c.code+','+JSON.stringify(nm)+','+JSON.stringify(tp2)+','+p);
    });
  });
  rows.push('','합계,,,,,'+t);
  var csv=rows.join('\n');
  var b=new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8'});
  var u=URL.createObjectURL(b);var a=document.createElement('a');a.href=u;a.download='KGM_견적.csv';a.click();URL.revokeObjectURL(u);
}
function eLdr2(show,text){
  document.getElementById('eLdr2').className='eldr2'+(show?' show':'');
  if(text)document.getElementById('eLT2').textContent=text;
}
function eTst2(msg){
  var t=document.getElementById('eTst2');t.textContent=msg;t.classList.add('show');
  setTimeout(function(){t.classList.remove('show');},2500);
}

// ─── 작업지시서 인쇄 도구 ───
(function(){
  var WO_LS = 'un_workorder_v1';
  var FIELDS = [
    { id:'wo-in-year',          label:'입고-년',      x:60,    y:50,   w:11, align:'center' },
    { id:'wo-in-month',         label:'입고-월',      x:71.5,  y:50.5, w:11, align:'center' },
    { id:'wo-in-day',           label:'입고-일',      x:84.5,  y:50.5, w:11, align:'center' },
    { id:'wo-carnum',           label:'차량번호',     x:243.5, y:23,   w:42 },
    { id:'wo-carmodel',         label:'차명',         x:243.5, y:29.5, w:42 },
    { id:'wo-km',               label:'주행거리',     x:242.5, y:37,   w:35, align:'right' },
    { id:'wo-phone',            label:'전화번호',     x:242.5, y:43.5, w:42 },
    { id:'wo-jacha-ins',        label:'자차 보험사',  x:242.5, y:65.5, w:35 },
    { id:'wo-jacha-receipt',    label:'자차 접수번호',x:243,   y:72.5, w:42 },
    { id:'wo-jacha-manager',    label:'자차 담당자',  x:243,   y:80,   w:42 },
    { id:'wo-daemul-ins',       label:'대물 보험사',  x:243.5, y:86.5, w:35 },
    { id:'wo-daemul-receipt',   label:'대물 접수번호',x:243.5, y:93.5, w:42 },
    { id:'wo-daemul-manager',   label:'대물 담당자',  x:242.5, y:100,  w:42 },
    { id:'wo-work-content',     label:'작업내용',     x:27,    y:71.5, w:96, h:95, multiline:true, lineHeight:7 },
    { id:'wo-customer-request', label:'고객요청',     x:128,   y:74,   w:88, h:20, multiline:true, lineHeight:5 }
  ];
  var FIELD_INPUT_IDS = FIELDS.map(function(f){return f.id;});

  var page = null;
  var offsetX = 0, offsetY = 0, fontSize = 13, zoom = 60;
  var currentMode = 'preview';
  var userPositions = {};
  var initialized = false;

  function loadState(){
    try {
      var raw = localStorage.getItem(WO_LS);
      if (!raw) return;
      var data = JSON.parse(raw);
      if (data.settings){
        if (typeof data.settings.offsetX === 'number') offsetX = data.settings.offsetX;
        if (typeof data.settings.offsetY === 'number') offsetY = data.settings.offsetY;
        if (typeof data.settings.fontSize === 'number') fontSize = data.settings.fontSize;
        if (typeof data.settings.zoom === 'number') zoom = data.settings.zoom;
      }
      if (data.positions) userPositions = data.positions;
    } catch(e) { console.error('wo loadState', e); }
  }
  function saveState(){
    try {
      localStorage.setItem(WO_LS, JSON.stringify({
        settings: { offsetX: offsetX, offsetY: offsetY, fontSize: fontSize, zoom: zoom },
        positions: userPositions
      }));
    } catch(e) { console.error('wo saveState', e); }
  }

  function getEffectivePos(f){
    var u = userPositions[f.id];
    return {
      x: ((u && typeof u.x === 'number') ? u.x : f.x) + offsetX,
      y: ((u && typeof u.y === 'number') ? u.y : f.y) + offsetY
    };
  }

  function createFields(){
    page.innerHTML = '';
    FIELDS.forEach(function(f){
      var el = document.createElement('div');
      el.className = 'wo-field';
      el.id = 'wo-overlay-' + f.id;
      el.dataset.fieldLabel = f.label;
      el.dataset.fId = f.id;
      page.appendChild(el);
      makeDraggable(el, f);
    });
    updatePositions();
  }

  function updatePositions(){
    FIELDS.forEach(function(f){
      var el = document.getElementById('wo-overlay-' + f.id);
      if (!el) return;
      var pos = getEffectivePos(f);
      el.style.left = pos.x + 'mm';
      el.style.top = pos.y + 'mm';
      el.style.width = f.w + 'mm';
      if (f.h) el.style.minHeight = f.h + 'mm';
      el.style.fontSize = fontSize + 'pt';
      if (f.align) el.style.textAlign = f.align;
      el.style.lineHeight = f.lineHeight ? (f.lineHeight + 'mm') : '1.2';
    });
  }

  function updateContent(){
    FIELDS.forEach(function(f){
      var input = document.getElementById(f.id);
      var overlay = document.getElementById('wo-overlay-' + f.id);
      if (!input || !overlay) return;
      overlay.textContent = input.value;
    });
  }

  function updateZoom(){
    if (!page) return;
    page.style.transform = 'scale(' + (zoom/100) + ')';
    var wrap = page.parentElement;
    if (wrap) { wrap.style.minHeight = (210 * 3.78 * (zoom/100)) + 'px'; }
  }

  function makeDraggable(el, fieldDef){
    var dragging = false, startMX, startMY, startFX, startFY;
    el.addEventListener('mousedown', function(e){
      if (currentMode !== 'adjust') return;
      e.preventDefault();
      dragging = true;
      startMX = e.clientX; startMY = e.clientY;
      var cur = userPositions[fieldDef.id] || { x: fieldDef.x, y: fieldDef.y };
      startFX = cur.x; startFY = cur.y;
      el.style.zIndex = 100;
    });
    document.addEventListener('mousemove', function(e){
      if (!dragging) return;
      var mmPerPx = 1 / (3.7795 * zoom/100);
      var dx = (e.clientX - startMX) * mmPerPx;
      var dy = (e.clientY - startMY) * mmPerPx;
      userPositions[fieldDef.id] = {
        x: Math.round((startFX + dx) * 2) / 2,
        y: Math.round((startFY + dy) * 2) / 2
      };
      updatePositions();
    });
    document.addEventListener('mouseup', function(){
      if (dragging){ dragging = false; el.style.zIndex = ''; saveState(); }
    });
  }

  window._woSetMode = function(mode, btn){
    currentMode = mode;
    document.querySelectorAll('#workOrderModal .wo-mode-tabs button').forEach(function(b){ b.classList.remove('active'); });
    if (btn) btn.classList.add('active');
    page.classList.remove('print-mode','adjust-mode');
    if (mode === 'real') page.classList.add('print-mode');
    else if (mode === 'adjust') page.classList.add('adjust-mode');
  };

  window._woClearInputs = function(){
    if (!confirm('모든 입력 내용을 지우시겠습니까? (위치 조정은 유지됩니다)')) return;
    FIELD_INPUT_IDS.forEach(function(id){ var el = document.getElementById(id); if (el) el.value = ''; });
    updateContent();
  };

  window._woResetPositions = function(){
    if (!confirm('모든 필드 위치를 기본값으로 되돌리시겠습니까?')) return;
    userPositions = {};
    offsetX = 0; offsetY = 0;
    var ox = document.getElementById('wo-offset-x'); if (ox){ ox.value = 0; }
    var oy = document.getElementById('wo-offset-y'); if (oy){ oy.value = 0; }
    document.getElementById('wo-offset-x-val').textContent = '0';
    document.getElementById('wo-offset-y-val').textContent = '0';
    updatePositions();
    saveState();
  };

  window._woPrint = function(){
    document.body.classList.add('printing-workorder');
    setTimeout(function(){
      window.print();
      setTimeout(function(){ document.body.classList.remove('printing-workorder'); }, 200);
    }, 50);
  };

  function setupSliders(){
    var ox = document.getElementById('wo-offset-x');
    var oy = document.getElementById('wo-offset-y');
    var fs = document.getElementById('wo-font-size');
    var zm = document.getElementById('wo-zoom');
    ox.value = offsetX; document.getElementById('wo-offset-x-val').textContent = offsetX.toFixed(1);
    oy.value = offsetY; document.getElementById('wo-offset-y-val').textContent = offsetY.toFixed(1);
    fs.value = fontSize; document.getElementById('wo-font-size-val').textContent = fontSize.toFixed(1);
    zm.value = zoom; document.getElementById('wo-zoom-val').textContent = zoom + '%';
    ox.addEventListener('input', function(e){ offsetX = parseFloat(e.target.value); document.getElementById('wo-offset-x-val').textContent = offsetX.toFixed(1); updatePositions(); saveState(); });
    oy.addEventListener('input', function(e){ offsetY = parseFloat(e.target.value); document.getElementById('wo-offset-y-val').textContent = offsetY.toFixed(1); updatePositions(); saveState(); });
    fs.addEventListener('input', function(e){ fontSize = parseFloat(e.target.value); document.getElementById('wo-font-size-val').textContent = fontSize.toFixed(1); updatePositions(); saveState(); });
    zm.addEventListener('input', function(e){ zoom = parseInt(e.target.value, 10); document.getElementById('wo-zoom-val').textContent = zoom + '%'; updateZoom(); saveState(); });
  }

  function setupInputs(){
    FIELD_INPUT_IDS.forEach(function(id){
      var el = document.getElementById(id);
      if (!el) return;
      el.addEventListener('input', updateContent);
    });
  }

  function init(){
    if (initialized) return;
    page = document.getElementById('wo-page');
    if (!page) return;
    loadState();
    setupSliders();
    setupInputs();
    createFields();
    updateContent();
    updateZoom();
    var overlay = document.getElementById('workOrderModal');
    if (overlay) {
      overlay.addEventListener('click', function(e){
        if (e.target === overlay) window._closeWorkOrder();
      });
    }
    initialized = true;
  }

  function splitDate(iso){
    if (!iso) return { y:'', m:'', d:'' };
    var parts = String(iso).split('-');
    if (parts.length < 3) return { y:'', m:'', d:'' };
    var yy = parts[0].slice(-2);
    return { y: yy, m: parts[1], d: parts[2] };
  }

  window._openWorkOrder = function(recordId){
    init();
    var rec = (typeof window._getRecord === 'function') ? window._getRecord(recordId) : null;
    if (rec){
      var d = splitDate(rec.inDate);
      var byId = function(id, v){ var el = document.getElementById(id); if (el) el.value = v || ''; };
      byId('wo-in-year', d.y);
      byId('wo-in-month', d.m);
      byId('wo-in-day', d.d);
      byId('wo-carnum', rec.carNum);
      byId('wo-carmodel', rec.carModel);
      byId('wo-km', rec.km);
      byId('wo-phone', rec.phone);
      byId('wo-jacha-ins', rec.insJacha);
      byId('wo-jacha-receipt', rec.jachaReceipt);
      byId('wo-jacha-manager', rec.jachaManager);
      byId('wo-daemul-ins', rec.insDaemul);
      byId('wo-daemul-receipt', rec.daemulReceipt);
      byId('wo-daemul-manager', rec.daemulManager);
      byId('wo-work-content', rec.repair);
      byId('wo-customer-request', rec.memo);
      updateContent();
    }
    document.getElementById('workOrderModal').classList.add('open');
  };

  window._closeWorkOrder = function(){
    document.getElementById('workOrderModal').classList.remove('open');
  };
})();

// ─── 차량 사진 업로드/조회/삭제 (admin 전용) ───
(function(){
  var STAGE_LABEL = { intake: '입고', outbound: '출고' };
  var currentRecordId = null;
  var currentStage = 'intake';
  var lightboxList = [];
  var lightboxIdx = 0;

  // long edge 1600px / quality 0.8 클라이언트 압축
  function compressImage(file, maxEdge, quality) {
    return new Promise(function(resolve, reject){
      var img = new Image();
      var url = URL.createObjectURL(file);
      img.onload = function(){
        URL.revokeObjectURL(url);
        var w = img.naturalWidth, h = img.naturalHeight;
        var scale = Math.min(1, maxEdge / Math.max(w, h));
        var cw = Math.round(w * scale), ch = Math.round(h * scale);
        var canvas = document.createElement('canvas');
        canvas.width = cw; canvas.height = ch;
        var ctx = canvas.getContext('2d');
        ctx.drawImage(img, 0, 0, cw, ch);
        canvas.toBlob(function(blob){
          if (!blob) return reject(new Error('compress failed'));
          resolve(blob);
        }, 'image/jpeg', quality);
      };
      img.onerror = function(){ URL.revokeObjectURL(url); reject(new Error('image load failed')); };
      img.src = url;
    });
  }

  function safeCarKey(carNum) {
    return encodeURIComponent(String(carNum || 'unknown').replace(/\s+/g,''));
  }

  function getRecord() {
    return currentRecordId && window._getRecord ? window._getRecord(currentRecordId) : null;
  }
  function getPhotoArr(stage) {
    var r = getRecord();
    return (r && r.photos && r.photos[stage]) || [];
  }

  window._openPhotoModal = function(recordId, stage) {
    currentRecordId = recordId;
    currentStage = stage || 'intake';
    var r = getRecord();
    if (!r) return;
    document.getElementById('photoModalTitle').textContent = ' ' + STAGE_LABEL[currentStage] + '사진 — ' + (r.carNum || '');
    document.getElementById('photoProgress').style.display = 'none';
    document.getElementById('photoProgress').textContent = '';
    var isAdmin = (window._userRole === 'admin');
    var capBtn = document.getElementById('photoCaptureBtn');
    var pickBtn = document.getElementById('photoPickBtn');
    var delBtn = document.getElementById('lightboxDeleteBtn');
    if (capBtn) capBtn.style.display = isAdmin ? '' : 'none';
    if (pickBtn) pickBtn.style.display = isAdmin ? '' : 'none';
    if (delBtn) delBtn.style.display = isAdmin ? '' : 'none';
    window._renderPhotoGrid();
    document.getElementById('photoModal').classList.add('open');
  };

  window._renderPhotoGrid = function() {
    var gridEl = document.getElementById('photoGrid');
    var emptyEl = document.getElementById('photoEmpty');
    var dlBtn = document.getElementById('photoDownloadAllBtn');
    if (!gridEl) return;
    var arr = getPhotoArr(currentStage);
    if (dlBtn) dlBtn.disabled = !arr.length;
    if (!arr.length) {
      gridEl.innerHTML = '';
      if (emptyEl) emptyEl.style.display = '';
      return;
    }
    if (emptyEl) emptyEl.style.display = 'none';
    gridEl.innerHTML = arr.map(function(p, idx){
      return '<div class="photo-thumb" data-idx="'+idx+'" onclick="window._openLightbox('+idx+')" style="position:relative;aspect-ratio:1/1;background:var(--bg);border:1px solid var(--border);border-radius:8px;overflow:hidden;cursor:pointer;">'
        + '<img src="'+esc(p.url||'')+'" alt="" loading="lazy" style="width:100%;height:100%;object-fit:cover;">'
        + '</div>';
    }).join('');
  };

  // 전체 사진 공유 — 2단계 클릭 패턴 (iOS NotAllowedError 회피)
  window._shareAllPhotos = async function() {
    if (!navigator.share) {
      showNotif('[1] 이 브라우저는 공유 미지원. 휴대폰 Safari/Chrome에서 시도해주세요', true);
      return;
    }
    var btn = document.getElementById('photoShareAllBtn');
    var origLabel = btn ? btn.textContent : '';
    var origBg = btn ? btn.style.background : '';
    // 두번째 클릭: 준비된 파일 즉시 공유
    if (_pendingShare && _pendingShare.kind === 'multi' && Date.now() - _pendingShare.ts < 60000) {
      var p = _pendingShare;
      _clearPendingShare();
      try {
        await navigator.share({ files: p.files, title: p.title, text: p.text });
        showNotif('공유 완료', false);
      } catch (e) {
        if (e.name === 'AbortError') return;
        _showShareError('전체 공유 · 2단계', e);
      }
      return;
    }
    // 첫번째 클릭: 사진 준비
    var arr = getPhotoArr(currentStage);
    if (!arr.length) { showNotif('공유할 사진이 없습니다', true); return; }
    var r = getRecord();
    var carNum = (r && r.carNum) ? r.carNum : 'vehicle';
    var progEl = document.getElementById('photoProgress');
    progEl.style.display = '';
    if (btn) { btn.disabled = true; }
    var files = [];
    var fetchFails = 0;
    var totalBytes = 0;
    for (var i = 0; i < arr.length; i++) {
      var p = arr[i];
      progEl.textContent = '사진 준비 중... (' + (i+1) + '/' + arr.length + ')';
      try {
        var resp = await fetch(p.url);
        if (!resp.ok) throw new Error('HTTP ' + resp.status);
        var blob = await resp.blob();
        // 압축으로 용량 줄여서 공유 한도 회피
        var compressed = await _compressForShare(blob);
        totalBytes += compressed.size;
        var fname = _safeFileName(carNum + '_' + currentStage + '_' + String(i+1).padStart(2,'0')) + '.jpg';
        files.push(new File([compressed], fname, { type: 'image/jpeg' }));
      } catch(e) {
        fetchFails++;
        console.warn('share fetch fail', p.url, e);
      }
    }
    if (!files.length) {
      progEl.textContent = '[2] 사진 가져오기 실패 — Firebase Storage CORS 또는 네트워크 (실패 ' + fetchFails + '건)';
      setTimeout(function(){ progEl.style.display = 'none'; }, 4000);
      if (btn) { btn.disabled = false; btn.textContent = origLabel; btn.style.background = origBg; }
      return;
    }
    if (navigator.canShare && !navigator.canShare({ files: files })) {
      progEl.textContent = '[3] 이 기기는 다중 파일 공유 미지원 — 한 장씩 공유해주세요';
      setTimeout(function(){ progEl.style.display = 'none'; }, 4000);
      if (btn) { btn.disabled = false; btn.textContent = origLabel; btn.style.background = origBg; }
      return;
    }
    var totalMB = (totalBytes / 1024 / 1024).toFixed(1);
    if (totalBytes > 40 * 1024 * 1024) {
      progEl.textContent = '[size] 압축 후 총 ' + totalMB + 'MB — 너무 큼. 사진 수를 줄이거나 한 장씩 공유해주세요';
      setTimeout(function(){ progEl.style.display = 'none'; }, 5000);
      if (btn) { btn.disabled = false; btn.textContent = origLabel; btn.style.background = origBg; }
      return;
    }
    // 준비 완료 → 두번째 클릭 대기 (iOS Web Share는 신선한 user gesture 안에서만 호출 가능)
    _pendingShare = {
      kind: 'multi', files: files,
      title: carNum + ' 입출고 사진 ' + files.length + '장',
      text: carNum + ' (' + currentStage + ')',
      ts: Date.now(),
      restoreBtn: function() {
        if (btn) { btn.disabled = false; btn.textContent = origLabel || ' 카톡으로 전체 보내기'; btn.style.background = origBg || '#FEE500'; }
      }
    };
    if (btn) {
      btn.disabled = false;
      btn.textContent = ' 한 번 더 눌러서 카톡으로 보내기';
      btn.style.background = '#34c759';
      btn.style.color = '#fff';
    }
    progEl.textContent = '준비 완료 (' + files.length + '장 · ' + totalMB + 'MB) — 위 초록 버튼을 한 번 더 눌러주세요';
    // 60초 후 자동 복원
    setTimeout(function() {
      if (_pendingShare && _pendingShare.ts && Date.now() - _pendingShare.ts >= 60000) {
        _clearPendingShare();
        if (progEl) progEl.style.display = 'none';
      }
    }, 60000);
  };

  // JSZip을 필요 시점에 로드 (페이지 초기엔 로드 안 됨 → 사진 모달에서 바로 쓰려면 직접 로드)
  function ensureJSZip() {
    return new Promise(function(res){
      if (typeof JSZip !== 'undefined') { res(true); return; }
      if (window._loadXlsx) {
        window._loadXlsx(function(){ res(typeof JSZip !== 'undefined'); });
      } else {
        var s = document.createElement('script');
        s.src = 'https://cdnjs.cloudflare.com/ajax/libs/jszip/3.10.1/jszip.min.js';
        s.onload = function(){ res(typeof JSZip !== 'undefined'); };
        s.onerror = function(){ res(false); };
        document.head.appendChild(s);
      }
    });
  }
  // 폴백: fetch가 막히거나(CORS) JSZip이 없을 때 한 장씩 받기
  async function downloadEachPhoto(arr, carNum, progEl) {
    var done = 0;
    for (var i = 0; i < arr.length; i++) {
      var p = arr[i];
      if (progEl) progEl.textContent = '한 장씩 받는 중... (' + (i+1) + '/' + arr.length + ')';
      var fileName = carNum + '_' + currentStage + '_' + String(i+1).padStart(2,'0') + '.jpg';
      try {
        var resp = await fetch(p.url);
        if (!resp.ok) throw new Error('HTTP ' + resp.status);
        var blob = await resp.blob();
        var burl = URL.createObjectURL(blob);
        var a = document.createElement('a');
        a.href = burl; a.download = fileName;
        document.body.appendChild(a); a.click(); document.body.removeChild(a);
        setTimeout((function(u){ return function(){ URL.revokeObjectURL(u); }; })(burl), 2000);
        done++;
      } catch(e) {
        // cross-origin이라 fetch 불가 → 새 탭으로 열어 직접 저장
        var a2 = document.createElement('a');
        a2.href = p.url; a2.target = '_blank'; a2.rel = 'noopener';
        document.body.appendChild(a2); a2.click(); document.body.removeChild(a2);
      }
      await new Promise(function(r){ setTimeout(r, 500); }); // 브라우저 연속 다운로드 차단 완화
    }
    return done;
  }
  window._downloadAllPhotos = async function() {
    if (window._userRole !== 'admin') return;
    var arr = getPhotoArr(currentStage);
    if (!arr.length) { showNotif('다운로드할 사진이 없습니다', true); return; }
    var r = getRecord();
    var carNum = (r && r.carNum) ? r.carNum : 'vehicle';
    var progEl = document.getElementById('photoProgress');
    progEl.style.display = '';
    // JSZip 미로드 시 즉시 로드
    if (typeof JSZip === 'undefined') {
      progEl.textContent = '압축 라이브러리 불러오는 중...';
      await ensureJSZip();
    }
    if (typeof JSZip === 'undefined') {
      // 그래도 없으면 한 장씩 받기로 폴백
      var n0 = await downloadEachPhoto(arr, carNum, progEl);
      progEl.textContent = '완료 — ' + n0 + '장 받음 (압축 불가로 개별 저장)';
      setTimeout(function(){ progEl.style.display = 'none'; }, 3000);
      return;
    }
    var zip = new JSZip();
    var done = 0, fail = 0;
    for (var i = 0; i < arr.length; i++) {
      var p = arr[i];
      progEl.textContent = 'ZIP 만드는 중... (' + (i+1) + '/' + arr.length + ')';
      try {
        var resp = await fetch(p.url);
        if (!resp.ok) throw new Error('HTTP ' + resp.status);
        var blob = await resp.blob();
        var fname = carNum + '_' + currentStage + '_' + String(i+1).padStart(2,'0') + '.jpg';
        zip.file(fname, blob);
        done++;
      } catch(e) {
        console.error('fetch failed for', p.url, e);
        fail++;
      }
    }
    if (!done) {
      // 전부 fetch 실패(대개 Storage CORS) → 한 장씩 받기로 폴백
      progEl.textContent = '묶음 다운로드 불가 — 한 장씩 받습니다';
      var n1 = await downloadEachPhoto(arr, carNum, progEl);
      progEl.textContent = '완료 — ' + n1 + '장 받음 (개별 저장)';
      setTimeout(function(){ progEl.style.display = 'none'; }, 3500);
      return;
    }
    progEl.textContent = 'ZIP 생성 중...';
    try {
      var zipBlob = await zip.generateAsync({ type: 'blob' });
      var url = URL.createObjectURL(zipBlob);
      var a = document.createElement('a');
      a.href = url;
      a.download = carNum + '_' + currentStage + '_사진.zip';
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      setTimeout(function(){ URL.revokeObjectURL(url); }, 1000);
      progEl.textContent = '완료 — ' + done + '장 다운로드' + (fail ? ' (' + fail + '장 실패)' : '');
    } catch(e) {
      progEl.textContent = 'ZIP 생성 실패: ' + e.message;
    }
    setTimeout(function(){ progEl.style.display = 'none'; }, 2500);
  };

  window._handlePhotoFiles = async function(fileList) {
    if (window._userRole !== 'admin') return;
    if (!fileList || !fileList.length) return;
    var r = getRecord();
    if (!r) return;
    var carKey = safeCarKey(r.carNum);
    var progEl = document.getElementById('photoProgress');
    progEl.style.display = '';
    var total = fileList.length, done = 0, fail = 0;
    var newMeta = [];
    for (var i = 0; i < total; i++) {
      var file = fileList[i];
      progEl.textContent = '업로드 중... (' + (i+1) + '/' + total + ') ' + file.name;
      try {
        var blob = await compressImage(file, 1600, 0.8);
        var ts = Date.now();
        var rand = Math.random().toString(36).slice(2, 8);
        var path = 'vehicles/' + carKey + '/' + currentStage + '/' + ts + '_' + rand + '.jpg';
        var sref = window._sRef(window._storage, path);
        await window._uploadBytes(sref, blob, { contentType: 'image/jpeg' });
        var url = await window._getDownloadURL(sref);
        newMeta.push({ url: url, path: path, uploadedAt: ts, size: blob.size });
        done++;
      } catch(e) {
        console.error('upload failed', file.name, e);
        fail++;
      }
    }
    if (newMeta.length) {
      var existing = getPhotoArr(currentStage);
      var merged = existing.concat(newMeta);
      try {
        await window._fbUpdate(
          window._fbRef(window._fbDb, 'records/' + currentRecordId + '/photos'),
          { [currentStage]: merged }
        );
        window._renderPhotoGrid();
      } catch(e) {
        showNotif('DB 저장 실패: ' + e.message, true);
      }
    }
    progEl.textContent = '완료 — 성공 ' + done + '장' + (fail ? ', 실패 ' + fail + '장' : '');
    setTimeout(function(){ progEl.style.display = 'none'; }, 2500);
    var pc = document.getElementById('photoCamera'); if (pc) pc.value = '';
    var pp = document.getElementById('photoPicker'); if (pp) pp.value = '';
  };

  // ── 인-앱 카메라 (연속 촬영) ──
  var camStream = null;
  var camPendingBlobs = []; // [{ blob, thumbUrl }]

  function _camUpdateUI() {
    var n = camPendingBlobs.length;
    var countEl = document.getElementById('camCount');
    var doneBtn = document.getElementById('camDone');
    var pendingEl = document.getElementById('camPending');
    if (countEl) countEl.textContent = n + '장';
    if (doneBtn) {
      doneBtn.textContent = '업로드 ' + n;
      doneBtn.disabled = (n === 0);
      doneBtn.style.opacity = (n === 0) ? '0.4' : '1';
    }
    if (pendingEl) {
      if (!n) {
        pendingEl.style.display = 'none';
        pendingEl.innerHTML = '';
      } else {
        pendingEl.style.display = '';
        pendingEl.innerHTML = camPendingBlobs.map(function(item, idx){
          return '<div style="display:inline-block;position:relative;width:64px;height:64px;margin-right:6px;border-radius:6px;overflow:hidden;border:2px solid rgba(255,255,255,0.4);vertical-align:middle;">'
            + '<img src="'+esc(item.thumbUrl)+'" style="width:100%;height:100%;object-fit:cover;">'
            + '<button onclick="window._camRemovePending('+idx+')" style="position:absolute;top:0;right:0;background:rgba(0,0,0,0.7);color:#fff;border:none;width:20px;height:20px;font-size:11px;cursor:pointer;border-radius:0 0 0 6px;">×</button>'
            + '</div>';
        }).join('');
      }
    }
  }

  window._camRemovePending = function(idx) {
    var item = camPendingBlobs[idx];
    if (item && item.thumbUrl) try { URL.revokeObjectURL(item.thumbUrl); } catch(e){}
    camPendingBlobs.splice(idx, 1);
    _camUpdateUI();
  };

  window._openCameraModal = async function() {
    if (window._userRole !== 'admin') return;
    var r = getRecord();
    if (!r) return;
    document.getElementById('camTitle').textContent = ' ' + STAGE_LABEL[currentStage] + '사진 — ' + (r.carNum || '');
    var modal = document.getElementById('cameraModal');
    var video = document.getElementById('camVideo');
    var errEl = document.getElementById('camError');
    errEl.style.display = 'none';
    modal.style.display = 'flex';
    camPendingBlobs = [];
    _camUpdateUI();
    if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
      errEl.textContent = '이 브라우저는 카메라를 지원하지 않습니다.';
      errEl.style.display = '';
      return;
    }
    try {
      camStream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: { ideal: 'environment' }, width: { ideal: 1920 }, height: { ideal: 1080 } },
        audio: false
      });
      video.srcObject = camStream;
    } catch(e) {
      console.error('camera error', e);
      errEl.innerHTML = '카메라 접근 실패: ' + esc(e.message || e.name) + '<br><br>브라우저 주소창의 카메라 권한을 허용으로 변경해주세요.';
      errEl.style.display = '';
    }
  };

  function _stopCamera() {
    if (camStream) {
      try { camStream.getTracks().forEach(function(t){ t.stop(); }); } catch(e){}
      camStream = null;
    }
    var video = document.getElementById('camVideo');
    if (video) video.srcObject = null;
  }

  window._closeCameraModal = function() {
    if (camPendingBlobs.length && !confirm('찍은 사진 ' + camPendingBlobs.length + '장이 업로드되지 않았습니다. 정말 닫으시겠습니까?')) return;
    camPendingBlobs.forEach(function(item){ if (item.thumbUrl) try { URL.revokeObjectURL(item.thumbUrl); } catch(e){} });
    camPendingBlobs = [];
    _stopCamera();
    document.getElementById('cameraModal').style.display = 'none';
  };

  window._cameraCapture = function() {
    var video = document.getElementById('camVideo');
    var canvas = document.getElementById('camCanvas');
    if (!video || !video.videoWidth) { showNotif('카메라 준비 중입니다', true); return; }
    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;
    var ctx = canvas.getContext('2d');
    ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
    canvas.toBlob(function(blob){
      if (!blob) { showNotif('캡쳐 실패', true); return; }
      var thumbUrl = URL.createObjectURL(blob);
      camPendingBlobs.push({ blob: blob, thumbUrl: thumbUrl });
      _camUpdateUI();
      // 셔터 시각 피드백
      var btn = document.getElementById('camShutter');
      if (btn) { btn.style.transform = 'scale(0.92)'; setTimeout(function(){ btn.style.transform = ''; }, 100); }
    }, 'image/jpeg', 0.92);
  };

  window._cameraDone = async function() {
    if (!camPendingBlobs.length) return;
    var blobs = camPendingBlobs.slice();
    // 카메라는 닫고 사진 모달에서 업로드 진행 (진행률 표시 활용)
    camPendingBlobs.forEach(function(item){ if (item.thumbUrl) try { URL.revokeObjectURL(item.thumbUrl); } catch(e){} });
    camPendingBlobs = [];
    _stopCamera();
    document.getElementById('cameraModal').style.display = 'none';
    // _handlePhotoFiles는 File 객체를 받지만 Blob도 동일하게 동작 (compressImage가 URL.createObjectURL로 처리)
    // 각 Blob에 name 부여 (압축 전 진행률 표기용)
    var fileLike = blobs.map(function(item, i){
      try { return new File([item.blob], 'capture_' + (i+1) + '.jpg', { type: 'image/jpeg' }); }
      catch(e) { return item.blob; }
    });
    await window._handlePhotoFiles(fileLike);
  };

  window._openLightbox = function(idx) {
    lightboxList = getPhotoArr(currentStage);
    if (!lightboxList.length) return;
    lightboxIdx = Math.max(0, Math.min(idx, lightboxList.length - 1));
    var lb = document.getElementById('photoLightbox');
    lb.style.display = 'flex';
    _updateLightbox();
  };

  function _updateLightbox() {
    var item = lightboxList[lightboxIdx];
    if (!item) return;
    document.getElementById('lightboxImg').src = item.url || '';
    document.getElementById('lightboxCounter').textContent = (lightboxIdx + 1) + ' / ' + lightboxList.length;
  }

  window._closeLightbox = function() {
    document.getElementById('photoLightbox').style.display = 'none';
  };

  window._lightboxNav = function(delta) {
    if (!lightboxList.length) return;
    lightboxIdx = (lightboxIdx + delta + lightboxList.length) % lightboxList.length;
    _updateLightbox();
  };

  // 공유용 이미지 압축 — 긴 변 1600px, JPEG 85% (Web Share API 총 용량 한도 회피)
  // 500KB 미만은 압축 안 함 (이미 작음)
  async function _compressForShare(blob) {
    try {
      if (!blob || blob.size < 500 * 1024) return blob;
      var url = URL.createObjectURL(blob);
      try {
        var img = await new Promise(function(res, rej){
          var i = new Image();
          i.onload = function(){ res(i); };
          i.onerror = function(){ rej(new Error('decode fail')); };
          i.src = url;
        });
        var w = img.naturalWidth, h = img.naturalHeight;
        var MAX = 1600;
        if (w > MAX || h > MAX) {
          var ratio = MAX / Math.max(w, h);
          w = Math.round(w * ratio);
          h = Math.round(h * ratio);
        }
        var canvas = document.createElement('canvas');
        canvas.width = w; canvas.height = h;
        canvas.getContext('2d').drawImage(img, 0, 0, w, h);
        var out = await new Promise(function(res){
          canvas.toBlob(function(b){ res(b); }, 'image/jpeg', 0.85);
        });
        return out && out.size < blob.size ? out : blob;
      } finally {
        URL.revokeObjectURL(url);
      }
    } catch(e) {
      console.warn('compress failed, using original', e);
      return blob;
    }
  }

  // 공유 준비 캐시 (2단계 클릭 패턴 — iOS NotAllowedError 회피)
  var _pendingShare = null;  // { kind:'single'|'multi', files, title, text, ts, restoreBtn }

  function _clearPendingShare() {
    if (_pendingShare && _pendingShare.restoreBtn) _pendingShare.restoreBtn();
    _pendingShare = null;
  }

  // 파일명 ASCII로 정규화 — 한글·공백·특수문자가 일부 안드로이드 공유 타겟(카톡 등)에서 실패 유발
  function _safeFileName(s) {
    var ascii = String(s || 'photo')
      .replace(/[^\w\-]/g, '_')   // 영숫자·_·- 외 전부 _ 로
      .replace(/_+/g, '_')         // 연속 _ 정리
      .replace(/^_|_$/g, '');      // 양끝 _ 제거
    return ascii || 'photo';
  }

  // 공유 에러를 사용자가 정확히 읽을 수 있는 모달로 표시 (showNotif는 짧아서 잘림)
  function _showShareError(stage, err) {
    var nm = (err && err.name) || 'Error';
    var msg = (err && err.message) || String(err);
    console.error('[share error]', stage, nm, msg, err);
    var overlay = document.createElement('div');
    overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.85);z-index:9999;display:flex;align-items:center;justify-content:center;padding:20px;';
    overlay.onclick = function(e){ if (e.target === overlay) document.body.removeChild(overlay); };
    overlay.innerHTML = ''
      + '<div style="background:#1f1f1f;border:1px solid #444;border-radius:12px;padding:24px;max-width:90vw;color:#fff;font-size:14px;line-height:1.6;">'
      +   '<div style="font-size:18px;font-weight:700;margin-bottom:14px;color:#ef4444;"> 공유 실패 (' + stage + ')</div>'
      +   '<div style="margin-bottom:6px;"><b style="color:#fbbf24;">유형:</b> ' + nm + '</div>'
      +   '<div style="margin-bottom:14px;word-break:break-word;"><b style="color:#fbbf24;">메시지:</b> ' + msg + '</div>'
      +   '<div style="font-size:12px;color:#a3a3a3;line-height:1.7;">'
      +     '이 화면을 캡처해서 관리자에게 보내주세요. 한 장씩 공유 시도해보거나, " 전체 다운로드" 후 갤러리에서 카톡으로 보내는 방법도 있습니다.'
      +   '</div>'
      +   '<button onclick="this.closest(\'div[style*=fixed]\').remove()" style="margin-top:18px;padding:10px 20px;background:#444;color:#fff;border:none;border-radius:6px;font-size:13px;cursor:pointer;width:100%;">닫기</button>'
      + '</div>';
    document.body.appendChild(overlay);
  }

  // 1장 공유 — 2단계 클릭 패턴
  window._lightboxShare = async function() {
    if (!navigator.share) {
      showNotif('[1] 이 브라우저는 공유 미지원. 휴대폰 Safari/Chrome에서 시도해주세요', true);
      return;
    }
    // 두번째 클릭: 이미 준비된 파일이 있으면 즉시 share() 호출 (새로운 user gesture)
    if (_pendingShare && _pendingShare.kind === 'single' && Date.now() - _pendingShare.ts < 60000) {
      var p = _pendingShare;
      _clearPendingShare();
      try {
        await navigator.share({ files: p.files, title: p.title, text: p.text });
      } catch (e) {
        if (e.name === 'AbortError') return;
        _showShareError('1장 공유 · 2단계', e);
      }
      return;
    }
    // 첫번째 클릭: 사진 준비
    var item = lightboxList[lightboxIdx];
    if (!item) return;
    var r = getRecord();
    var carNum = (r && r.carNum) ? r.carNum : 'vehicle';
    // 파일명은 ASCII로 — 한글/공백이 안드로이드 카톡 등에서 실패 원인
    var fileName = _safeFileName(carNum + '_' + currentStage + '_' + (lightboxIdx + 1)) + '.jpg';
    var btn = document.querySelector('#photoLightbox button[onclick="window._lightboxShare()"]');
    var origLabel = btn ? btn.textContent : '';
    var origBg = btn ? btn.style.background : '';
    if (btn) { btn.textContent = '⏳ 준비 중...'; btn.disabled = true; }
    try {
      var resp = await fetch(item.url);
      if (!resp.ok) throw new Error('HTTP ' + resp.status);
      var blob = await resp.blob();
      var compressed = await _compressForShare(blob);
      var file = new File([compressed], fileName, { type: 'image/jpeg' });
      if (navigator.canShare && !navigator.canShare({ files: [file] })) {
        showNotif('[3] 이 기기는 파일 공유 미지원 — 다운로드로 대체', true);
        if (btn) { btn.textContent = origLabel; btn.disabled = false; }
        window._lightboxDownload();
        return;
      }
      // 준비 완료 → 두번째 클릭 대기
      _pendingShare = {
        kind: 'single', files: [file],
        title: carNum + ' 입출고 사진', text: carNum + ' (' + currentStage + ')',
        ts: Date.now(),
        restoreBtn: function() {
          if (btn) { btn.textContent = origLabel || ' 카톡 보내기'; btn.style.background = origBg || '#FEE500'; btn.disabled = false; }
        }
      };
      if (btn) {
        btn.textContent = ' 한 번 더 눌러 보내기';
        btn.style.background = '#34c759';
        btn.style.color = '#fff';
        btn.disabled = false;
      }
      showNotif('준비 완료 — 위 버튼을 한 번 더 눌러주세요', false);
      // 60초 후 자동 복원
      setTimeout(function() {
        if (_pendingShare && _pendingShare.ts && Date.now() - _pendingShare.ts >= 60000) _clearPendingShare();
      }, 60000);
    } catch (e) {
      console.warn('lightbox prepare failed:', e);
      showNotif('[2] 사진 준비 실패 — ' + (e.message || e), true);
      if (btn) { btn.textContent = origLabel; btn.style.background = origBg; btn.disabled = false; }
    }
  };

  window._lightboxDownload = async function() {
    var item = lightboxList[lightboxIdx];
    if (!item) return;
    var r = getRecord();
    var fileName = (r && r.carNum ? r.carNum : 'vehicle') + '_' + currentStage + '_' + (lightboxIdx + 1) + '.jpg';
    // 우선 fetch+blob로 진짜 파일 다운로드 시도 (CORS 통과 필요)
    try {
      var resp = await fetch(item.url);
      if (!resp.ok) throw new Error('HTTP ' + resp.status);
      var blob = await resp.blob();
      var blobUrl = URL.createObjectURL(blob);
      var a = document.createElement('a');
      a.href = blobUrl;
      a.download = fileName;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      setTimeout(function(){ URL.revokeObjectURL(blobUrl); }, 1000);
      return;
    } catch(e) {
      console.warn('lightbox fetch fallback:', e);
    }
    // 폴백: cross-origin이라 다운로드 안 되면 새 탭에서 열기 (사용자가 직접 저장)
    var a2 = document.createElement('a');
    a2.href = item.url;
    a2.target = '_blank';
    a2.rel = 'noopener';
    document.body.appendChild(a2);
    a2.click();
    document.body.removeChild(a2);
  };

  window._lightboxDelete = async function() {
    if (window._userRole !== 'admin') return;
    var item = lightboxList[lightboxIdx];
    if (!item) return;
    if (!confirm('이 사진을 삭제하시겠습니까?')) return;
    // Storage 삭제 (best-effort)
    if (item.path) {
      try { await window._deleteObject(window._sRef(window._storage, item.path)); }
      catch(e) { console.warn('storage delete failed (proceeding):', e); }
    }
    // DB에서 제거
    var existing = getPhotoArr(currentStage);
    var newArr = existing.filter(function(p){ return p.path !== item.path; });
    try {
      await window._fbUpdate(
        window._fbRef(window._fbDb, 'records/' + currentRecordId + '/photos'),
        { [currentStage]: newArr }
      );
      lightboxList = newArr;
      if (!lightboxList.length) window._closeLightbox();
      else { if (lightboxIdx >= lightboxList.length) lightboxIdx = lightboxList.length - 1; _updateLightbox(); }
      window._renderPhotoGrid();
      showNotif('삭제되었습니다');
    } catch(e) { showNotif('DB 갱신 실패: ' + e.message, true); }
  };

  // 키보드 단축키: ESC 닫기, 좌우 화살표 탐색
  document.addEventListener('keydown', function(e) {
    var lb = document.getElementById('photoLightbox');
    if (!lb || lb.style.display === 'none') return;
    if (e.key === 'Escape') window._closeLightbox();
    else if (e.key === 'ArrowLeft') window._lightboxNav(-1);
    else if (e.key === 'ArrowRight') window._lightboxNav(1);
  });
})();

// ─── 대시보드 출고예정 사이드바 토글 + 드래그 (PC 마우스 전용, localStorage 저장) ───
(function(){
  var aside = document.getElementById('dashOutSide');
  var handle = document.getElementById('dashOutDrag');
  if (!aside || !handle) return;
  var LS_KEY = 'un_outSchedule_pos_v1';
  var LS_VIS = 'un_outSchedule_visible_v1';

  function clamp(val, lo, hi) { return Math.max(lo, Math.min(val, hi)); }

  function applyPos(left, top) {
    var w = aside.offsetWidth || 220;
    var headerEl = document.querySelector('.header');
    var headerH = headerEl ? headerEl.offsetHeight : 90;
    var minTop = (headerH > window.innerHeight * 0.55 ? 84 : headerH) + 8; // 좌측 고정 헤더는 전체 높이라 보정
    var maxX = window.innerWidth - w;
    var maxY = window.innerHeight - 40; // 핸들 최소 노출
    aside.style.left = clamp(left, 0, Math.max(0, maxX)) + 'px';
    aside.style.top = clamp(top, minTop, Math.max(minTop, maxY)) + 'px';
    aside.style.right = 'auto';
    aside.style.bottom = 'auto';
  }

  // 표시 상태 복원 (기본: 숨김)
  aside.classList.add('hidden');
  try { localStorage.setItem(LS_VIS, '0'); } catch(e) {}
  syncToggleBtn();

  function syncToggleBtn() {
    var btn = document.getElementById('dashOutToggleBtn');
    if (btn) btn.classList.toggle('active', !aside.classList.contains('hidden'));
  }

  window._toggleDashOutSide = function(forceState) {
    var willShow = (typeof forceState === 'boolean') ? forceState : aside.classList.contains('hidden');
    aside.classList.toggle('hidden', !willShow);
    try { localStorage.setItem(LS_VIS, willShow ? '1' : '0'); } catch(e){}
    syncToggleBtn();
  };

  // 저장된 위치 복원
  try {
    var raw = localStorage.getItem(LS_KEY);
    if (raw) {
      var p = JSON.parse(raw);
      if (typeof p.left === 'number' && typeof p.top === 'number') applyPos(p.left, p.top);
    }
  } catch(e){}

  var dragging = false, sx = 0, sy = 0, sLeft = 0, sTop = 0;

  handle.addEventListener('mousedown', function(e){
    if (e.button !== 0) return; // 좌클릭만
    if (e.target && e.target.classList && e.target.classList.contains('dash-out-close')) return; //  버튼은 드래그 X
    e.preventDefault();
    dragging = true;
    sx = e.clientX; sy = e.clientY;
    var rect = aside.getBoundingClientRect();
    sLeft = rect.left; sTop = rect.top;
    aside.classList.add('dragging');
    document.body.style.userSelect = 'none';
  });

  document.addEventListener('mousemove', function(e){
    if (!dragging) return;
    applyPos(sLeft + (e.clientX - sx), sTop + (e.clientY - sy));
  });

  document.addEventListener('mouseup', function(){
    if (!dragging) return;
    dragging = false;
    aside.classList.remove('dragging');
    document.body.style.userSelect = '';
    var rect = aside.getBoundingClientRect();
    try { localStorage.setItem(LS_KEY, JSON.stringify({ left: rect.left, top: rect.top })); } catch(e){}
  });

  // 창 크기 변경 시 화면 밖으로 나간 사이드바 클램프
  window.addEventListener('resize', function(){
    var rect = aside.getBoundingClientRect();
    applyPos(rect.left, rect.top);
  });
})();

// ─── 예약차 사이드바 (Firebase RTDB reservations 경로) ───
(function(){
  var aside = document.getElementById('dashResSide');
  var handle = document.getElementById('dashResDrag');
  if (!aside || !handle) return;
  var LS_KEY = 'un_reservations_pos_v1';
  var LS_VIS = 'un_reservations_visible_v1';
  var reservations = {};
  var editingResId = null;

  function clamp(val, lo, hi) { return Math.max(lo, Math.min(val, hi)); }
  function applyPos(left, top) {
    var w = aside.offsetWidth || 240;
    var headerEl = document.querySelector('.header');
    var headerH = headerEl ? headerEl.offsetHeight : 90;
    var minTop = (headerH > window.innerHeight * 0.55 ? 84 : headerH) + 8;
    var maxX = window.innerWidth - w;
    var maxY = window.innerHeight - 40;
    aside.style.left = clamp(left, 0, Math.max(0, maxX)) + 'px';
    aside.style.top = clamp(top, minTop, Math.max(minTop, maxY)) + 'px';
    aside.style.right = 'auto';
    aside.style.bottom = 'auto';
  }

  aside.classList.add('hidden');
  try { localStorage.setItem(LS_VIS, '0'); } catch(e) {}
  syncToggleBtn();

  function syncToggleBtn() {
    var btn = document.getElementById('dashResToggleBtn');
    if (btn) btn.classList.toggle('active', !aside.classList.contains('hidden'));
  }

  window._toggleDashResSide = function(forceState) {
    var willShow = (typeof forceState === 'boolean') ? forceState : aside.classList.contains('hidden');
    aside.classList.toggle('hidden', !willShow);
    try { localStorage.setItem(LS_VIS, willShow ? '1' : '0'); } catch(e){}
    syncToggleBtn();
  };

  try {
    var raw = localStorage.getItem(LS_KEY);
    if (raw) {
      var p = JSON.parse(raw);
      if (typeof p.left === 'number' && typeof p.top === 'number') applyPos(p.left, p.top);
    }
  } catch(e){}

  // Firebase RTDB 구독 (window._fbDb, window._fbRef은 module script에서 노출됨)
  function startRes() {
    if (!window._fbDb || !window._fbRef) { setTimeout(startRes, 300); return; }
    var resRef = window._fbRef(window._fbDb, 'reservations');
    // onValue가 module에서 import됐는데 다른 script에서는 접근 불가 — 새로 등록 필요
    // 대신 module이 expose한 db로 onValue를 동적 import
    import('https://www.gstatic.com/firebasejs/10.12.0/firebase-database.js').then(function(mod){
      mod.onValue(resRef, function(snap){
        reservations = snap.val() || {};
        renderResList();
      });
    });
  }
  startRes();

  function renderResList() {
    var listEl = document.getElementById('resSideList');
    var cntEl = document.getElementById('resSideCnt');
    if (!listEl) return;
    var entries = Object.entries(reservations).filter(function(e){ return e[1]; });
    // 예약일 빠른 순
    entries.sort(function(a,b){ return (a[1].reserveDate||'').localeCompare(b[1].reserveDate||''); });
    if (cntEl) cntEl.textContent = entries.length;
    if (!entries.length) {
      listEl.innerHTML = '<div class="empty-mini">등록된 예약차가 없습니다</div>';
      return;
    }
    listEl.innerHTML = entries.map(function(en){
      var id = en[0], r = en[1];
      var carLabel = (r.carNum && r.carModel) ? (esc(r.carNum) + ' · ' + esc(r.carModel))
                   : (r.carNum ? esc(r.carNum) : (r.carModel ? esc(r.carModel) : '(차량 미입력)'));
      var phone = r.phone ? '<a href="tel:'+esc(String(r.phone).replace(/[^0-9+]/g,''))+'" onclick="event.stopPropagation();" style="color:var(--text);text-decoration:none;"> '+esc(r.phone)+'</a>' : '';
      var dateLine = r.reserveDate ? ('<span style="color:var(--accent);"> '+esc(r.reserveDate)+'</span>') : '';
      var meta = [
        r.name ? '<span class="nm">'+esc(r.name)+'</span>' : '',
        phone,
        dateLine
      ].filter(Boolean).join(' &nbsp; ');
      var memo = r.memo ? '<div style="font-size:11px;color:var(--text-dim);margin-top:4px;white-space:pre-wrap;line-height:1.4;">'+esc(r.memo)+'</div>' : '';
      return '<div class="item" onclick="window._editRes(\''+esc(id)+'\')">'
        + '<div class="car">'+carLabel+'</div>'
        + (meta ? '<div class="meta">'+meta+'</div>' : '')
        + memo
        + '</div>';
    }).join('');
  }

  function resetForm() {
    editingResId = null;
    document.getElementById('resModalTitle').textContent = ' 예약차 등록';
    document.getElementById('resDeleteBtn').style.display = 'none';
    ['res-carnum','res-carmodel','res-name','res-phone','res-memo'].forEach(function(k){
      var el = document.getElementById(k); if (el) el.value = '';
    });
    document.getElementById('res-date').value = '';
  }

  window._openResModal = function() {
    resetForm();
    document.getElementById('resModal').classList.add('open');
  };

  window._editRes = function(id) {
    var r = reservations[id]; if (!r) return;
    editingResId = id;
    document.getElementById('resModalTitle').textContent = ' 예약차 수정';
    document.getElementById('resDeleteBtn').style.display = '';
    document.getElementById('res-carnum').value = r.carNum || '';
    document.getElementById('res-carmodel').value = r.carModel || '';
    document.getElementById('res-name').value = r.name || '';
    document.getElementById('res-phone').value = r.phone || '';
    document.getElementById('res-date').value = r.reserveDate || '';
    document.getElementById('res-memo').value = r.memo || '';
    document.getElementById('resModal').classList.add('open');
  };

  window._saveRes = async function() {
    var data = {
      carNum: document.getElementById('res-carnum').value.trim(),
      carModel: document.getElementById('res-carmodel').value.trim(),
      name: document.getElementById('res-name').value.trim(),
      phone: document.getElementById('res-phone').value.trim(),
      reserveDate: document.getElementById('res-date').value || '',
      memo: document.getElementById('res-memo').value.trim(),
      updatedAt: new Date().toISOString(),
      updatedBy: window._userEmail || ''
    };
    if (!data.carNum && !data.carModel && !data.name && !data.phone && !data.memo) {
      if (typeof showNotif === 'function') showNotif('최소 한 항목 이상 입력해주세요', true);
      return;
    }
    var btn = document.getElementById('resSaveBtn');
    btn.disabled = true; btn.textContent = '저장 중...';
    try {
      var mod = await import('https://www.gstatic.com/firebasejs/10.12.0/firebase-database.js');
      if (editingResId) {
        await mod.update(window._fbRef(window._fbDb, 'reservations/' + editingResId), data);
        if (typeof showNotif === 'function') showNotif('예약차 정보가 수정되었습니다');
      } else {
        data.createdAt = new Date().toISOString();
        data.createdBy = window._userEmail || '';
        await mod.push(window._fbRef(window._fbDb, 'reservations'), data);
        if (typeof showNotif === 'function') showNotif('예약차가 등록되었습니다');
      }
      document.getElementById('resModal').classList.remove('open');
    } catch(e) {
      if (typeof showNotif === 'function') showNotif('저장 실패: ' + e.message, true);
      else alert('저장 실패: ' + e.message);
    }
    btn.disabled = false; btn.textContent = '저장';
  };

  window._deleteRes = async function() {
    if (!editingResId) return;
    if (!confirm('이 예약차를 삭제하시겠습니까?')) return;
    try {
      var mod = await import('https://www.gstatic.com/firebasejs/10.12.0/firebase-database.js');
      await mod.remove(window._fbRef(window._fbDb, 'reservations/' + editingResId));
      if (typeof showNotif === 'function') showNotif('삭제되었습니다');
      document.getElementById('resModal').classList.remove('open');
    } catch(e) {
      if (typeof showNotif === 'function') showNotif('삭제 실패: ' + e.message, true);
    }
  };

  var dragging = false, sx = 0, sy = 0, sLeft = 0, sTop = 0;
  handle.addEventListener('mousedown', function(e){
    if (e.button !== 0) return;
    if (e.target && e.target.classList && e.target.classList.contains('dash-out-close')) return;
    e.preventDefault();
    dragging = true;
    sx = e.clientX; sy = e.clientY;
    var rect = aside.getBoundingClientRect();
    sLeft = rect.left; sTop = rect.top;
    aside.classList.add('dragging');
    document.body.style.userSelect = 'none';
  });
  document.addEventListener('mousemove', function(e){
    if (!dragging) return;
    applyPos(sLeft + (e.clientX - sx), sTop + (e.clientY - sy));
  });
  document.addEventListener('mouseup', function(){
    if (!dragging) return;
    dragging = false;
    aside.classList.remove('dragging');
    document.body.style.userSelect = '';
    var rect = aside.getBoundingClientRect();
    try { localStorage.setItem(LS_KEY, JSON.stringify({ left: rect.left, top: rect.top })); } catch(e){}
  });
  window.addEventListener('resize', function(){
    var rect = aside.getBoundingClientRect();
    applyPos(rect.left, rect.top);
  });

  // 모달 백드롭 닫기
  var resModal = document.getElementById('resModal');
  if (resModal) resModal.addEventListener('click', function(e) {
    if (e.target === this) this.classList.remove('open');
  });
})();

// PWA 서비스워커 등록 (/un/ 범위만)
if ('serviceWorker' in navigator) {
  window.addEventListener('load', function() {
    navigator.serviceWorker.register('sw.js', { scope: './' })
      .catch(function(err) { console.warn('SW 등록 실패:', err); });
  });
  // 자동 새로고침(controllerchange→reload)은 로그인 흐름과 충돌 가능 — 비활성화.
  // 새 버전은 수동 새로고침(Ctrl+Shift+R)으로 받음.
}

// PWA 설치 안내 — Android는 beforeinstallprompt, iOS는 안내 문구만
(function () {
  var deferredPrompt = null;
  var banner = document.getElementById('pwaBanner');
  var btnInstall = document.getElementById('pwaInstallBtn');
  var btnHeader = document.getElementById('pwaHeaderBtn');

  // 이미 standalone(설치된 상태로 켬)이면 안내 자체 안 보임
  var isStandalone = window.matchMedia('(display-mode: standalone)').matches
    || window.navigator.standalone === true; // iOS
  if (isStandalone) return;

  // iOS Safari 감지 (beforeinstallprompt 미지원 → 안내 문구만)
  var ua = navigator.userAgent;
  var isIOS = /iPhone|iPad|iPod/.test(ua) && !window.MSStream;
  var isSafari = /^((?!chrome|android|crios|fxios|edgios).)*safari/i.test(ua);

  if (isIOS && isSafari) {
    if (banner) { banner.classList.add('show', 'ios'); }
    // iOS는 헤더 아이콘은 효과 없으니 숨김 유지
  }

  window.addEventListener('beforeinstallprompt', function (e) {
    e.preventDefault();
    deferredPrompt = e;
    if (banner) { banner.classList.add('show', 'android'); }
    if (btnHeader) { btnHeader.classList.add('show'); }
  });

  function triggerInstall() {
    if (!deferredPrompt) return;
    deferredPrompt.prompt();
    deferredPrompt.userChoice.then(function (choice) {
      console.log('PWA 설치 결과:', choice.outcome);
      deferredPrompt = null;
      if (banner) banner.classList.remove('show');
      if (btnHeader) btnHeader.classList.remove('show');
    });
  }

  if (btnInstall) btnInstall.addEventListener('click', triggerInstall);
  if (btnHeader) btnHeader.addEventListener('click', triggerInstall);

  window.addEventListener('appinstalled', function () {
    deferredPrompt = null;
    if (banner) banner.classList.remove('show');
    if (btnHeader) btnHeader.classList.remove('show');
  });
})();
